    tw.t = Math.min(1, tw.t + Math.min(dt, 1 / 20) / 0.9);
    const e = easeInOut(tw.t);
    for (let i = 0; i < current.length; i++) current[i] = tw.from[i] + (tw.to[i] - tw.from[i]) * e;
