          onClick={(e) => { if (e.delta > 4) return; e.stopPropagation(); const i = pick(g.kind, e); onSelect(i === live.current.selected ? null : i); }}
        />
      ))}
      <lineSegments geometry={edgeGeometry} material={edgeMaterial} frustumCulled={false} ref={lineRef} />
    </>
  );
});

